using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;using MashBoxSDK.AnimationStudio;
public static class StudioOrientationToolbarValidation {
 public static void Run(){int count=0;try{AnimationStudioWindow.Open();var host=Resources.FindObjectsOfTypeAll<AnimationStudioWindow>().First();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(AnimationStudioWindow).GetMethod("SwitchStudioMode",flags).Invoke(host,new object[]{true});var editor=host.ToolbarModelEditor;var view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().First(v=>v.Studio==host);var dropdown=new StudioToolbarOrientation();dropdown.containerWindow=view;view.rootVisualElement.Add(dropdown);typeof(StudioToolbarOrientation).GetMethod("Bind",flags).Invoke(dropdown,null);int changes=0;view.StudioToolbarStateChanged+=()=>changes++;editor.SetToolbarLocalAxes(true);view.SyncStudioToolbarState(true);foreach(var mode in new[]{"Component","Object","World","Component","World","Object"}){int before=changes;if(mode=="Component")editor.SetToolbarComponentAxes();else editor.SetToolbarLocalAxes(mode=="Object");view.SyncStudioToolbarState();if(dropdown.text!=mode)throw new Exception("Stale dropdown: "+dropdown.text+" expected "+mode);count++;if(changes!=before+1)throw new Exception("Missing state notification for "+mode);count++;view.SyncStudioToolbarState();if(changes!=before+1)throw new Exception("Unchanged state notified again");count++;}dropdown.RemoveFromHierarchy();File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../orientation-toolbar-result.txt")),"PASS "+count+" retained toolbar label and notification checks");EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../orientation-toolbar-result.txt")),e.ToString());EditorApplication.Exit(1);}}
}
